functions.sane_case:
static inline int sane_case(int x, int high)
{
    if (((sane_ctype[(unsigned char)(x)] & (0x04)) != 0))
        x = (x & ~0x20) | high;
    return x;
}

functions.tm_to_time_t:
static time_t tm_to_time_t(const struct atm *tm)
{
    static const int mdays[] = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};
    int year = tm->tm_year - 70;
    int month = tm->tm_mon;
    int day = tm->tm_mday;
    if (year < 0 || year > 129)
        return -1;
    if (month < 0 || month > 11)
        return -1;
    if (month < 2 || (year + 2) % 4)
        day--;
    if (tm->tm_hour < 0 || tm->tm_min < 0 || tm->tm_sec < 0)
        return -1;
    return (year * 365 + (year + 1) / 4 + mdays[month] + day) * 24 * 60 * 60UL + tm->tm_hour * 60 * 60 +
           tm->tm_min * 60 + tm->tm_sec;
}

functions.match_string:
static int match_string(const char *date, const char *str)
{
    int i = 0;
    for (i = 0; *date; date++, str++, i++)
    {
        if (*date == *str)
            continue;
        if (sane_case((unsigned char)(*date), 0) == sane_case((unsigned char)(*str), 0))
            continue;
        if (!((sane_ctype[(unsigned char)(*date)] & (0x04 | 0x02)) != 0))
            break;
        return 0;
    }
    return i;
}

