functions.match_alpha:
static int match_alpha(const char *date, struct atm *tm, int *offset)
{
    int i;
    for (i = 0; i < 12; i++)
    {
        int match = match_string(date, month_names[i]);
        if (match >= 3)
        {
            tm->tm_mon = i;
            return match;
        }
    }
    for (i = 0; i < 7; i++)
    {
        int match = match_string(date, weekday_names[i]);
        if (match >= 3)
        {
            tm->tm_wday = i;
            return match;
        }
    }
    for (i = 0; i < (sizeof(timezone_names) / sizeof(timezone_names[0])); i++)
    {
        int match = match_string(date, timezone_names[i].name);
        if (match >= 3 || match == strlen(timezone_names[i].name))
        {
            int off = timezone_names[i].offset;
            off += timezone_names[i].dst;
            if (*offset == -1)
                *offset = 60 * off;
            return match;
        }
    }
    if (match_string(date, "PM") == 2)
    {
        tm->tm_hour = (tm->tm_hour % 12) + 12;
        return 2;
    }
    if (match_string(date, "AM") == 2)
    {
        tm->tm_hour = (tm->tm_hour % 12) + 0;
        return 2;
    }
    return skip_alpha(date);
}

functions.is_date:
static int is_date(int year, int month, int day, struct atm *now_tm, time_t now, struct atm *tm)
{
    if (month > 0 && month < 13 && day > 0 && day < 32)
    {
        struct atm check = *tm;
        struct atm *r = (now_tm ? &check : tm);
        r->tm_mon = month - 1;
        r->tm_mday = day;
        if (year == -1)
        {
            if (!now_tm)
                return 1;
            r->tm_year = now_tm->tm_year;
        }
        else if (year >= 1970 && year < 2100)
            r->tm_year = year - 1900;
        else if (year > 70 && year < 100)
            r->tm_year = year;
        else if (year < 38)
            r->tm_year = year + 100;
        else
            return 0;
        if (!now_tm)
            return 1;
        tm->tm_mon = r->tm_mon;
        tm->tm_mday = r->tm_mday;
        if (year != -1)
            tm->tm_year = r->tm_year;
        return 1;
    }
    return 0;
}

functions.match_multi_number:
static int match_multi_number(unsigned long num, char c, const char *date, char *end, struct atm *tm, time_t now)
{
    long num2, num3, num4;
    num2 = strtol(end + 1, &end, 10);
    num3 = -1;
    num4 = 0;
    if (*end == c && ((sane_ctype[(unsigned char)(end[1])] & (0x02)) != 0))
    {
        num3 = strtol(end + 1, &end, 10);
        if (*end == '.')
        {
            char *start = end + 1;
            num4 = strtol(end + 1, &end, 10);
            if ((end - start) < 6)
            {
                num4 *= (long)pow(10, 6 - (end - start));
            }
        }
    }
    switch (c)
    {
    case ':':
        if (num3 < 0)
            num3 = 0;
        if (num < 25 && num2 >= 0 && num2 < 60 && num3 >= 0 && num3 <= 60)
        {
            tm->tm_hour = num;
            tm->tm_min = num2;
            tm->tm_sec = num3;
            tm->tm_usec = num4;
            break;
        }
        return 0;
    case '-':
    case '/':
    case '.':
        if (!now)
            now = time(((void *)0));
        if (num > 70)
        {
            if (is_date(num, num2, num3, ((void *)0), now, tm))
                break;
            if (is_date(num, num3, num2, ((void *)0), now, tm))
                break;
        }
        if (c != '.' && is_date(num3, num, num2, ((void *)0), now, tm))
            break;
        if (is_date(num3, num2, num, ((void *)0), now, tm))
            break;
        if (c == '.' && is_date(num3, num, num2, ((void *)0), now, tm))
            break;
        return 0;
    }
    return end - date;
}

