functions.approxidate_alpha:
static const char *approxidate_alpha(const char *date, struct atm *tm, struct atm *now, int *num, int *touched)
{
    const struct typelen *tl;
    const struct special *s;
    const char *end = date;
    int i;
    while (((sane_ctype[(unsigned char)(*++end)] & (0x04)) != 0))
        ;
    for (i = 0; i < 12; i++)
    {
        int match = match_string(date, month_names[i]);
        if (match >= 3)
        {
            tm->tm_mon = i;
            *touched = 1;
            return end;
        }
    }
    for (s = special; s->name; s++)
    {
        int len = strlen(s->name);
        if (match_string(date, s->name) == len)
        {
            s->fn(tm, now, num);
            *touched = 1;
            return end;
        }
    }
    if (!*num)
    {
        for (i = 1; i < 11; i++)
        {
            int len = strlen(number_name[i]);
            if (match_string(date, number_name[i]) == len)
            {
                *num = i;
                *touched = 1;
                return end;
            }
        }
        if (match_string(date, "last") == 4)
        {
            *num = 1;
            *touched = 1;
        }
        return end;
    }
    tl = typelen;
    while (tl->type)
    {
        int len = strlen(tl->type);
        if (match_string(date, tl->type) >= len - 1)
        {
            update_tm(tm, now, tl->length * *num);
            *num = 0;
            *touched = 1;
            return end;
        }
        tl++;
    }
    for (i = 0; i < 7; i++)
    {
        int match = match_string(date, weekday_names[i]);
        if (match >= 3)
        {
            int diff, n = *num - 1;
            *num = 0;
            diff = tm->tm_wday - i;
            if (diff <= 0)
                n++;
            diff += 7 * n;
            update_tm(tm, now, diff * 24 * 60 * 60);
            *touched = 1;
            return end;
        }
    }
    if (match_string(date, "months") >= 5)
    {
        int n;
        update_tm(tm, now, 0);
        n = tm->tm_mon - *num;
        *num = 0;
        while (n < 0)
        {
            n += 12;
            tm->tm_year--;
        }
        tm->tm_mon = n;
        *touched = 1;
        return end;
    }
    if (match_string(date, "years") >= 4)
    {
        update_tm(tm, now, 0);
        tm->tm_year -= *num;
        *num = 0;
        *touched = 1;
        return end;
    }
    return end;
}

functions.approxidate_digit:
static const char *approxidate_digit(const char *date, struct atm *tm, int *num, time_t now)
{
    char *end;
    unsigned long number = strtoul(date, &end, 10);
    switch (*end)
    {
    case ':':
    case '.':
    case '/':
    case '-':
        if (((sane_ctype[(unsigned char)(end[1])] & (0x02)) != 0))
        {
            int match = match_multi_number(number, *end, date, end, tm, now);
            if (match)
                return date + match;
        }
    }
    if (date[0] != '0' || end - date <= 2)
        *num = number;
    return end;
}

functions.pending_number:
static void pending_number(struct atm *tm, int *num)
{
    int number = *num;
    if (number)
    {
        *num = 0;
        if (tm->tm_mday < 0 && number < 32)
            tm->tm_mday = number;
        else if (tm->tm_mon < 0 && number < 13)
            tm->tm_mon = number - 1;
        else if (tm->tm_year < 0)
        {
            if (number > 1969 && number < 2100)
                tm->tm_year = number - 1900;
            else if (number > 69 && number < 100)
                tm->tm_year = number;
            else if (number < 38)
                tm->tm_year = 100 + number;
        }
    }
}

functions.approxidate_str:
static int approxidate_str(const char *date, struct timeval *tv)
{
    int number = 0;
    int touched = 0;
    struct atm tm, now;
    time_t time_sec;
    time_sec = tv->tv_sec;
    localtime_r(&time_sec, (struct tm *)&tm);
    now = tm;
    tm.tm_year = -1;
    tm.tm_mon = -1;
    tm.tm_mday = -1;
    tm.tm_usec = tv->tv_usec;
    for (;;)
    {
        unsigned char c = *date;
        if (!c)
            break;
        date++;
        if (((sane_ctype[(unsigned char)(c)] & (0x02)) != 0))
        {
            pending_number(&tm, &number);
            date = approxidate_digit(date - 1, &tm, &number, time_sec);
            touched = 1;
            continue;
        }
        if (((sane_ctype[(unsigned char)(c)] & (0x04)) != 0))
            date = approxidate_alpha(date - 1, &tm, &now, &number, &touched);
    }
    pending_number(&tm, &number);
    if (!touched)
        return -1;
    tv->tv_usec = tm.tm_usec;
    tv->tv_sec = update_tm(&tm, &now, 0);
    return 0;
}

