functions.approxidate_relative:
int approxidate_relative(const char *date, struct timeval *tv, const struct timeval *relative_to)
{
    int offset;
    if (!parse_date_basic(date, tv, &offset))
    {
        return 0;
    }
    if (relative_to == ((void *)0))
    {
        gettimeofday(tv, ((void *)0));
    }
    else
    {
        *tv = *relative_to;
    }
    if (!approxidate_str(date, tv))
    {
        return 0;
    }
    return -1;
}
